	-- {spell:23101} Eye of Divinity · {area:2717} Molten Core · {npc:14494} Eris Havenfire
	["The epic priest staff: the {spell:23101} from {area:2717}, {npc:14494}'s peasant rescue, then the Eye of Shadow."] = "Le bâton épique du prêtre : l'{spell:23101} du {area:2717}, le sauvetage des paysans d'{npc:14494}, puis l'Œil de l'ombre.",

	-- Step 1: The Eye of Divinity
	-- {item:18646} The Eye of Divinity · {object:179703} Cache of the Firelord · {npc:12018} Majordomo Executus · {area:2717} Molten Core · {area:1584} Blackrock Depths · {item:18412} Core Fragment · {npc:14387} Lothos Riftwaker · {area:254} Blackrock Mountain · {npc:14494} Eris Havenfire
	["{item:18646} comes from the {object:179703}, the chest that appears when {npc:12018} yields in {area:2717}, a 40-player raid (it is in the cache about half the time). {area:2717}'s portal is at the bottom of {area:1584}; once you have done Attunement to the Core (a {item:18412} from beside that portal), {npc:14387} inside {area:254} ports you straight in. Nothing in this chain starts without the Eye: {npc:14494} is invisible until you equip it."] = "{item:18646} vient de la {object:179703}, le coffre qui apparaît quand {npc:12018} se rend dans le {area:2717}, un raid à 40 joueurs (il est dans la cache environ une fois sur deux). Le portail du {area:2717} se trouve au fond des {area:1584} ; une fois l'Harmonisation avec le Cœur faite (un {item:18412} pris à côté de ce portail), {npc:14387}, à l'intérieur du {area:254}, vous y téléporte directement. Rien dans cette suite ne commence sans l'Œil : {npc:14494} est invisible tant que vous ne l'équipez pas.",
	-- {npc:14387} Lothos Riftwaker · {area:2717} Molten Core
	["{npc:14387}: the way into {area:2717} once attuned"] = "{npc:14387} : l'accès au {area:2717} une fois harmonisé",
	-- {item:18646} The Eye of Divinity · {area:2717} Molten Core · {area:254} Blackrock Mountain
	["{item:18646}: {area:2717}, through {area:254}"] = "{item:18646} : {area:2717}, par le {area:254}",

	-- Step 2: Eris Havenfire
